additionalExercises.referenceSolution:
#include <stdio.h>

void print_row(char symbol, int count) {
    for (int i = 0; i < count; i++) {
        printf("%c", symbol);
    }
    printf("\n");
}

int main(void) {
    int n;
    char symbol;
    scanf("%d %c", &n, &symbol);
    for (int i = 1; i <= n; i++) {
        print_row(symbol, i);
    }
    return 0;
}

