    // Напишите тело функции. Функцию main писать не нужно.
    return 0;
}

additionalExercises.referenceSolution:
int digit_sum(long long n) {
    int sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum;
}

